def UniversalWeightLaw (f : Refinement P Q) (w : C → ℝ) (v : D → ℝ) : Prop :=
  ∀ (FD : Fintype D) (FK : ∀ d, Fintype (f.Copies d)),
    @Refinement.WeightLaw C D P Q FD f FK w v

